          alt: "มอเตอร์อยู่ซ้าย ขั้วบนต่อใบสวิตช์ขั้วที่ 1 ขั้วล่างต่อใบสวิตช์ขั้วที่ 2 ใบสวิตช์สองใบเชื่อมกลไกด้วยเส้นประ ทั้งคู่โยกไปหน้าสัมผัส a หน้าสัมผัส a ของขั้ว 1 กับ b ของขั้ว 2 ต่อกันด้วยสายน้ำตาลไปขั้วบวกแบตเตอรี่ 12 V ผ่านฟิวส์ 2 A หน้าสัมผัส b ของขั้ว 1 กับ a ของขั้ว 2 ต่อกันด้วยสายฟ้าไปขั้วลบ สายทั้งสองไขว้กันโดยไม่ต่อถึงกัน คำอธิบาย โยกขึ้น ขั้วบนมอเตอร์เป็นบวก หมุนตามเข็ม โยกลง ขั้วบนเป็นลบ หมุนทวนเข็ม",
