          md: "**วิธีที่ 2 การมอดูเลตความกว้างพัลส์ (pulse width modulation, PWM)** — ใช้สวิตช์อิเล็กทรอนิกส์ (MOSFET) **เปิด–ปิด** แรงดันเต็มค่าด้วยความถี่คงที่ แล้วปรับสัดส่วนเวลาที่เปิด เรียกว่า **วัฏจักรหน้าที่ (duty cycle, D)** ความเหนี่ยวนำของขดและความเฉื่อยของโรเตอร์ทำให้มอเตอร์ตอบสนองต่อ **แรงดันเฉลี่ย** ความถี่ PWM ที่ใช้กับมอเตอร์มักอยู่ระหว่างหลาย kHz ถึงราว 20 kHz (สูงกว่า 20 kHz จะไม่ได้ยินเสียงหวีด)",
