          alt: "สามแถวของคลื่นสี่เหลี่ยมระหว่าง 0 V กับ 12 V คาบเท่ากันทุกแถว แถวบน D 25% ช่วงสูงสั้น เส้นประแรงดันเฉลี่ย 3 V แถวกลาง D 50% เฉลี่ย 6 V แถวล่าง D 75% ช่วงสูงยาว เฉลี่ย 9 V ลูกศรแสดงช่วง t on และคาบ T",
