          caption: "วงจรควบคุม Start–Stop แบบยึดตัวเอง 24 V DC",
          alt: "วงจรควบคุมแนวตั้งจากราง +24 V สีน้ำตาลลงราง 0 V สีฟ้า ผ่านฟิวส์ F3 หน้าสัมผัส NC ของโอเวอร์โหลด F2 95–96 ปุ่ม Stop S0 แบบ NC แล้วแยกเป็นสองกิ่งขนาน ปุ่ม Start S1 แบบ NO และหน้าสัมผัสช่วย K1 13–14 แบบ NO ป้ายยึดตัวเอง สองกิ่งรวมกันเข้าขดลวด K1 A1–A2 ลงราง 0 V หลอด H1 ต่อขนานกับขดลวดและติดเมื่อ K1 ทำงาน",
