      check: "กำลังมอเตอร์ 8 × 1 = 8 W บวกสูญเสีย 4 W = 12 W ✓ ถ้าภาระเพิ่มจนกระแส 1.5 A แรงดันตกคร่อม R เป็น 6 V มอเตอร์เหลือ 6 V ความเร็วตกมาก",
