      check: "ถ้าลืม η และ PF จะได้ 1500/(1.732 × 400) ≈ 2.2 A ซึ่งต่ำเกินไป OL จะทริปทั้งที่มอเตอร์ทำงานปกติ กระแสจริงต้องมากกว่าเพราะมีการสูญเสียและกำลังรีแอกทีฟ ✓",
